import { test, expect } from '@playwright/test';

test.describe('Breadcrumb Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display breadcrumbs correctly for top-level navigation', async ({ page }) => {
    // Navigate to the home page
    await page.getByRole('main', { name: /home/i }).click();

    // Verify breadcrumbs are visible
    const breadcrumbs = page.getByRole('breadcrumb');
    await expect(breadcrumbs).toBeVisible();

    // Verify breadcrumb items are present
    const homeBreadcrumb = page.getByRole('link', { name: /home/i });
    await expect(homeBreadcrumb).toBeVisible();

    const aboutBreadcrumb = page.getByRole('link', { name: /about/i });
    await expect(aboutBreadcrumb).toBeVisible();

    const contactBreadcrumb = page.getByRole('link', { name: /contact/i });
    await expect(contactBreadcrumb).toBeVisible();

    // Verify breadcrumb text is correct
    await expect(homeBreadcrumb).toContainText('Home');
    await expect(aboutBreadcrumb).toContainText('About');
    await expect(contactBreadcrumb).toContainText('Contact');

    // Verify breadcrumb links are functional
    await expect(homeBreadcrumb).toHaveAttribute('href', '/');
    await expect(aboutBreadcrumb).toHaveAttribute('href', '/about');
    await expect(contactBreadcrumb).toHaveAttribute('href', '/contact');
  });

  test('should update breadcrumbs when navigating deeper into the site hierarchy', async ({ page }) => {
    // Navigate to the home page
    await page.getByRole('main', { name: /home/i }).click();

    // Navigate to the about page
    const aboutLink = page.getByRole('link', { name: /about/i });
    await aboutLink.click();

    // Verify breadcrumbs update to reflect current location
    const breadcrumbs = page.getByRole('breadcrumb');
    await expect(breadcrumbs).toBeVisible();

    const homeBreadcrumb = page.getByRole('link', { name: /home/i });
    await expect(homeBreadcrumb).toBeVisible();

    const aboutBreadcrumb = page.getByRole('link', { name: /about/i });
    await expect(aboutBreadcrumb).toBeVisible();

    // Verify breadcrumb text is correct
    await expect(homeBreadcrumb).toContainText('Home');
    await expect(aboutBreadcrumb).toContainText('About');

    // Verify breadcrumb links are functional
    await expect(homeBreadcrumb).toHaveAttribute('href', '/');
    await expect(aboutBreadcrumb).toHaveAttribute('href', '/about');

    // Navigate to a sub-page
    const servicesLink = page.getByRole('link', { name: /services/i });
    await servicesLink.click();

    // Verify breadcrumbs update to include sub-page
    const servicesBreadcrumb = page.getByRole('link', { name: /services/i });
    await expect(servicesBreadcrumb).toBeVisible();

    // Verify breadcrumb text includes sub-page
    await expect(aboutBreadcrumb).toContainText('About');
    await expect(servicesBreadcrumb).toContainText('Services');

    // Verify breadcrumb links are functional
    await expect(aboutBreadcrumb).toHaveAttribute('href', '/about');
    await expect(servicesBreadcrumb).toHaveAttribute('href', '/services');
  });
});
